grant create on schema api,app_private to git_tutor_commands;
create table app_private.calendar_connection_requests(id uuid primary key default gen_random_uuid(),connection_id uuid not null unique default gen_random_uuid(),actor_account_id uuid not null references app_private.accounts(id),session_id uuid not null,expires_at timestamptz not null default now()+interval '10 minutes',consumed_at timestamptz,command_id uuid not null,created_at timestamptz not null default now());
create table app_private.provider_connections(id uuid primary key,provider text not null check(provider='google'),mode text not null check(mode in('fake','google')),state text not null check(state in('connected','reauthorization_required','revoked')),organizer_email text not null,calendar_id text not null,approved_by uuid not null references app_private.accounts(id),credential_version uuid,version integer not null default 1 check(version>0),verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_connected_calendar on app_private.provider_connections(provider) where state='connected';
create table app_private.provider_credential_versions(id uuid primary key,connection_id uuid not null references app_private.provider_connections(id),encrypted_credentials jsonb not null,credential_key_id text not null,created_at timestamptz not null default now());
alter table app_private.provider_connections add foreign key(credential_version) references app_private.provider_credential_versions(id) deferrable initially deferred;
create table app_private.calendar_events(occurrence_id uuid primary key references app_private.occurrences(id),connection_id uuid not null references app_private.provider_connections(id),connection_version integer not null,provider_event_id text not null,meeting_generation integer not null default 1 check(meeting_generation>0),conference_request_id uuid not null default gen_random_uuid(),synced_occurrence_version integer,meeting_status text not null default 'pending' check(meeting_status in('pending','ready','failed','revoked')),join_url text,etag text,safe_error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.calendar_observations(id uuid primary key default gen_random_uuid(),occurrence_id uuid not null references app_private.occurrences(id),connection_id uuid not null references app_private.provider_connections(id),connection_version integer not null,occurrence_version integer not null,meeting_generation integer not null,job_id uuid not null references app_private.outbox_jobs(id),lease_token uuid not null,observation jsonb not null,applied boolean not null,created_at timestamptz not null default now(),unique(job_id,lease_token));
create table app_private.calendar_replacements(id uuid primary key default gen_random_uuid(),occurrence_id uuid not null references app_private.occurrences(id),meeting_generation integer not null,reason text not null,actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now());
alter table app_private.calendar_events add poll_count integer not null default 0,add notified_occurrence_version integer,add notified_generation integer;
create trigger calendar_credentials_immutable before update or delete on app_private.provider_credential_versions for each row execute function app_private.reject_immutable_change();
create trigger calendar_observations_immutable before update or delete on app_private.calendar_observations for each row execute function app_private.reject_immutable_change();
create trigger calendar_replacements_immutable before update or delete on app_private.calendar_replacements for each row execute function app_private.reject_immutable_change();
do $$declare name text;begin foreach name in array array['calendar_connection_requests','provider_connections','provider_credential_versions','calendar_events','calendar_observations','calendar_replacements'] loop execute format('alter table app_private.%I enable row level security',name);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',name);execute format('grant select,insert on app_private.%I to git_tutor_commands',name);execute format('create policy calendar_commands on app_private.%I to git_tutor_commands using(true) with check(true)',name);end loop;end $$;
grant update on app_private.calendar_connection_requests,app_private.provider_connections,app_private.calendar_events to git_tutor_commands;
create function app_private.calendar_envelope_valid(p_envelope jsonb,p_key text) returns boolean language sql immutable set search_path='' as $$ select coalesce(jsonb_typeof(p_envelope)='object' and p_envelope->>'v'='1' and p_envelope->>'alg'='A256GCM' and p_envelope->>'kid'=p_key and p_key ~ '^[A-Za-z0-9_-]{1,40}$' and p_envelope->>'nonce' ~ '^[A-Za-z0-9_-]{16}$' and p_envelope->>'tag' ~ '^[A-Za-z0-9_-]{22}$' and p_envelope->>'ciphertext' ~ '^[A-Za-z0-9_-]+$' and length(p_envelope::text)<=50000 and p_envelope-array['v','alg','kid','nonce','ciphertext','tag']='{}'::jsonb,false) $$;

create function app_private.calendar_queue_current() returns void language plpgsql security definer set search_path='' as $$declare o record;begin
 for o in select id,version from app_private.occurrences where state in('confirmed','in_progress') and end_at>now() loop perform app_private.enqueue_event(gen_random_uuid(),'calendar_connection_changed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version),'calendar.sync');end loop;
end $$;
create function api.get_calendar_connection_request(p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();r app_private.calendar_connection_requests%rowtype;begin
 perform app_private.require_role(actor,'admin');select * into r from app_private.calendar_connection_requests where id=p_request_id and actor_account_id=actor and session_id=(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid and consumed_at is null and expires_at>now();if r.id is null then raise exception 'NOT_FOUND';end if;return jsonb_build_object('request_id',r.id,'connection_id',r.connection_id,'expires_at',r.expires_at);
end $$;
create function api.connect_fake_calendar(p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;cid uuid:=gen_random_uuid();result jsonb;begin
 perform app_private.require_role(actor,'admin');if app_private.catalog_environment() not in('development','test') then raise exception 'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'connect_fake_calendar','{}',p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 perform pg_advisory_xact_lock(hashtextextended('calendar-organizer',0));update app_private.provider_connections set state='revoked',version=version+1,updated_at=now() where state='connected';
 insert into app_private.provider_connections(id,provider,mode,state,organizer_email,calendar_id,approved_by) values(cid,'google','fake','connected','organizer@example.test','synthetic@example.test',actor);
 perform app_private.calendar_queue_current();result:=app_private.booking_finish(ctx,cid,1,jsonb_build_object('connection_id',cid,'integration_state','simulated'),'calendar_connected',jsonb_build_object('connection_id',cid));perform set_config('response.status','201',true);return result;
end $$;
create function api.create_calendar_connection_request(p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;r app_private.calendar_connection_requests%rowtype;begin
 perform app_private.require_role(actor,'admin');ctx:=app_private.booking_begin(actor,'create_calendar_connection_request','{}',p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 insert into app_private.calendar_connection_requests(actor_account_id,session_id,command_id) values(actor,(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid,(ctx->>'command_id')::uuid) returning * into r;
 perform set_config('response.status','201',true);return app_private.booking_finish(ctx,r.id,1,jsonb_build_object('request_id',r.id,'connection_id',r.connection_id,'expires_at',r.expires_at),'calendar_connection_requested',jsonb_build_object('request_id',r.id));
end $$;
create function app_private.record_calendar_connection(p_request_id uuid,p_connection_id uuid,p_credential_version uuid,p_organizer_email text,p_calendar_id text,p_encrypted_credentials jsonb,p_credential_key_id text) returns jsonb language plpgsql security definer set search_path='' as $$declare r app_private.calendar_connection_requests%rowtype;c app_private.provider_connections%rowtype;begin
 select * into r from app_private.calendar_connection_requests where id=p_request_id for update;
 if r.id is null or r.connection_id is distinct from p_connection_id or r.expires_at<=now() or not app_private.auth_session_active(r.actor_account_id,r.session_id) or not app_private.payment_verified_account(r.actor_account_id) then raise exception 'AUTH_REQUIRED';end if;perform app_private.require_role(r.actor_account_id,'admin');
 if p_credential_version is null or p_organizer_email is null or length(p_organizer_email) not between 3 and 254 or p_organizer_email not like '%@%' or p_calendar_id is null or length(p_calendar_id) not between 1 and 500 or not app_private.calendar_envelope_valid(p_encrypted_credentials,p_credential_key_id) then raise exception 'VALIDATION_ERROR';end if;
 if r.consumed_at is not null then select * into c from app_private.provider_connections where id=r.connection_id;if c.credential_version is distinct from p_credential_version then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('connection_id',c.id,'version',c.version,'integration_state','verification_required');end if;
 perform pg_advisory_xact_lock(hashtextextended('calendar-organizer',0));update app_private.provider_connections set state='revoked',version=version+1,updated_at=now() where state='connected';
 insert into app_private.provider_connections(id,provider,mode,state,organizer_email,calendar_id,approved_by,credential_version) values(r.connection_id,'google','google','connected',p_organizer_email,p_calendar_id,r.actor_account_id,p_credential_version);
 insert into app_private.provider_credential_versions(id,connection_id,encrypted_credentials,credential_key_id) values(p_credential_version,r.connection_id,p_encrypted_credentials,p_credential_key_id);
 update app_private.calendar_connection_requests set consumed_at=now() where id=r.id;perform app_private.calendar_queue_current();
 insert into app_private.audit_events(actor_account_id,command_id,action,aggregate_id,details) values(r.actor_account_id,r.command_id,'calendar_connection_authorized',r.connection_id,jsonb_build_object('credential_version',p_credential_version));
 return jsonb_build_object('connection_id',r.connection_id,'version',1,'integration_state','verification_required');
end $$;
create function api.get_calendar_connection() returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();c app_private.provider_connections%rowtype;begin
 perform app_private.require_role(actor,'admin');select * into c from app_private.provider_connections order by (state='connected') desc,created_at desc,id desc limit 1;
 return jsonb_build_object('connection_id',c.id,'version',coalesce(c.version,0),'mode',coalesce(c.mode,'fake'),'state',coalesce(c.state,'not_connected'),'integration_state',case when c.mode='fake' then 'simulated' when c.verified_at is not null then 'verified' else 'verification_required' end,'organizer_masked_email',case when c.organizer_email is not null then left(c.organizer_email,1)||'***@'||split_part(c.organizer_email,'@',2) end,'last_verified_at',c.verified_at,'safe_error_code',null);
end $$;
create function api.revoke_calendar_connection(p_connection_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;c app_private.provider_connections%rowtype;begin
 perform app_private.require_role(actor,'admin');ctx:=app_private.booking_begin(actor,'revoke_calendar_connection',jsonb_build_object('connection_id',p_connection_id,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 select * into c from app_private.provider_connections where id=p_connection_id for update;if c.id is null then raise exception 'NOT_FOUND';end if;if p_expected_version is distinct from c.version then raise exception 'VERSION_CONFLICT';end if;
 update app_private.provider_connections set state='revoked',version=version+1,updated_at=now() where id=c.id;return app_private.booking_finish(ctx,c.id,c.version+1,'{}','calendar_connection_revoked',jsonb_build_object('connection_id',c.id));
end $$;

create function app_private.calendar_assert_access(p_actor uuid,p_occurrence_id uuid,p_view text,p_learner_id uuid) returns app_private.occurrences language plpgsql security definer set search_path='' as $$declare o app_private.occurrences%rowtype;learner uuid;begin
 select * into o from app_private.occurrences where id=p_occurrence_id;if o.id is null then raise exception 'NOT_FOUND';end if;
 if p_view='admin' then perform app_private.require_role(p_actor,'admin');
 elsif p_view='tutor' then perform app_private.require_role(p_actor,'tutor');if not exists(select 1 from app_private.tutors where id=o.tutor_id and account_id=p_actor) then raise exception 'NOT_FOUND';end if;
 elsif p_view='customer' then select e.learner_id into learner from app_private.enrollments e where e.occurrence_id=o.id and(p_learner_id is null or e.learner_id=p_learner_id) and app_private.booking_can_access(p_actor,e.learner_id) order by e.id limit 1;if learner is null then raise exception 'NOT_FOUND';end if;perform app_private.assert_learner_scope(p_actor,learner,'booking');
 else raise exception 'VALIDATION_ERROR';end if;return o;
end $$;
create function api.get_occurrence_meeting(p_occurrence_id uuid,p_view text default 'customer',p_learner_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();o app_private.occurrences%rowtype;m app_private.calendar_events%rowtype;c app_private.provider_connections%rowtype;reason text;status text;integration text;begin
 o:=app_private.calendar_assert_access(actor,p_occurrence_id,p_view,p_learner_id);select * into m from app_private.calendar_events where occurrence_id=o.id;select * into c from app_private.provider_connections where id=m.connection_id;
 integration:=case when c.mode='fake' then 'simulated' when c.verified_at is not null then 'verified' else 'verification_required' end;status:=coalesce(m.meeting_status,o.meeting_status);
 if o.state in('cancelled','completed') or o.end_at<=now() then reason:=case when o.state='cancelled' then 'ACCESS_REVOKED' else 'SESSION_ENDED' end;status:='revoked';
 elsif o.state not in('confirmed','in_progress') then reason:='NOT_CONFIRMED';
 elsif p_view='customer' and not exists(select 1 from app_private.enrollments e where e.occurrence_id=o.id and e.state='confirmed' and(p_learner_id is null or e.learner_id=p_learner_id) and app_private.booking_can_access(actor,e.learner_id)) then reason:='ACCESS_REVOKED';status:='revoked';
 elsif c.id is null then reason:='PROVISIONING';status:='pending';
 elsif c.state<>'connected' or not app_private.has_role(c.approved_by,'admin') or not app_private.payment_verified_account(c.approved_by) then reason:='AUTHORIZATION_REQUIRED';status:='failed';
 elsif not exists(select 1 from app_private.tutors t where t.id=o.tutor_id and app_private.has_role(t.account_id,'tutor') and app_private.payment_verified_account(t.account_id)) then reason:='ACCESS_REVOKED';status:='revoked';
 elsif m.synced_occurrence_version is distinct from o.version or m.connection_version<>c.version then reason:='PROVISIONING';status:='pending';
 elsif m.meeting_status='failed' then reason:='PROVIDER_FAILED';
 elsif m.meeting_status<>'ready' or m.join_url is null then reason:='PROVISIONING';
 elsif integration='verification_required' and p_view<>'admin' then reason:='LIVE_VERIFICATION_REQUIRED';end if;
 return jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'meeting_generation',coalesce(m.meeting_generation,0),'start_at',o.start_at,'end_at',o.end_at,'server_now',now(),'meeting_status',status,'integration_state',integration,'can_join',reason is null,'join_path',case when reason is null then '/api/v1/occurrences/'||o.id||'/meeting/access' end,'reason',reason);
end $$;
create function api.get_meeting_access(p_occurrence_id uuid,p_view text default 'customer',p_learner_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;link text;begin
 result:=api.get_occurrence_meeting(p_occurrence_id,p_view,p_learner_id);if not(result->>'can_join')::boolean then raise exception 'STATE_CONFLICT';end if;select join_url into link from app_private.calendar_events where occurrence_id=p_occurrence_id;return jsonb_build_object('occurrence_id',p_occurrence_id,'occurrence_version',result->'occurrence_version','meeting_generation',result->'meeting_generation','join_url',link,'integration_state',result->'integration_state');
end $$;
create function app_private.calendar_command(p_name text,p_occurrence_id uuid,p_reason text,p_expected_version integer,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;o app_private.occurrences%rowtype;m app_private.calendar_events%rowtype;job uuid;begin
 perform app_private.require_role(actor,'admin');if p_name not in('retry_meeting_provisioning','replace_meeting_access') then raise exception 'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,p_name,jsonb_build_object('occurrence_id',p_occurrence_id,'reason',p_reason,'expected_version',p_expected_version),p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;o:=app_private.booking_lock_occurrence(p_occurrence_id);if p_expected_version is distinct from o.version then raise exception 'VERSION_CONFLICT';end if;if o.state not in('confirmed','in_progress','cancelled') then raise exception 'STATE_CONFLICT';end if;
 if p_name='replace_meeting_access' then if p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;select * into m from app_private.calendar_events where occurrence_id=o.id for update;if m.occurrence_id is null then raise exception 'STATE_CONFLICT';end if;
 update app_private.calendar_events set meeting_generation=meeting_generation+1,conference_request_id=gen_random_uuid(),meeting_status='pending',join_url=null,synced_occurrence_version=null,updated_at=now() where occurrence_id=o.id returning * into m;
 insert into app_private.calendar_replacements(occurrence_id,meeting_generation,reason,actor_account_id,command_id) values(o.id,m.meeting_generation,p_reason,actor,(ctx->>'command_id')::uuid);end if;
 job:=app_private.enqueue_event(gen_random_uuid(),'calendar_sync_requested',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version),'calendar.sync');perform set_config('response.status','202',true);
 return app_private.booking_finish(ctx,o.id,o.version,jsonb_build_object('job_id',job)||case when p_name='replace_meeting_access' then jsonb_build_object('meeting_generation',m.meeting_generation) else '{}'::jsonb end,'calendar_sync_requested',jsonb_build_object('occurrence_id',o.id));
end $$;
create function api.retry_meeting_provisioning(p_occurrence_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.calendar_command('retry_meeting_provisioning',p_occurrence_id,null,p_expected_version,p_idempotency_key)$$;
create function api.replace_meeting_access(p_occurrence_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.calendar_command('replace_meeting_access',p_occurrence_id,p_reason,p_expected_version,p_idempotency_key)$$;

create function app_private.calendar_assert_job(p_occurrence_id uuid,p_job_id uuid,p_lease_token uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where j.id=p_job_id and j.purpose='calendar.sync' and j.state='leased' and j.lease_token=p_lease_token and j.lease_expires_at>now() and e.aggregate_id=p_occurrence_id and e.payload->>'occurrence_id'=p_occurrence_id::text) then raise exception 'LEASE_LOST';end if;
end $$;
create function app_private.prepare_calendar_sync(p_occurrence_id uuid,p_job_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare o app_private.occurrences%rowtype;c app_private.provider_connections%rowtype;m app_private.calendar_events%rowtype;email text;begin
 perform app_private.calendar_assert_job(p_occurrence_id,p_job_id,p_lease_token);o:=app_private.booking_lock_occurrence(p_occurrence_id);select * into c from app_private.provider_connections where state='connected' order by created_at desc,id desc limit 1;
 if c.id is null or not app_private.has_role(c.approved_by,'admin') or not app_private.payment_verified_account(c.approved_by) then return jsonb_build_object('state','suppressed','reason','CALENDAR_CONNECTION_REQUIRED');end if;
 if o.state not in('confirmed','in_progress','cancelled') then return jsonb_build_object('state','suppressed','reason','OCCURRENCE_NOT_ACTIVE');end if;
 select u.email into email from app_private.tutors t cross join lateral app_private.auth_account(t.account_id) u where t.id=o.tutor_id and app_private.has_role(t.account_id,'tutor') and app_private.payment_verified_account(t.account_id);
 if email is null then return jsonb_build_object('state','suppressed','reason','TUTOR_AUTHORITY_REQUIRED');end if;
 insert into app_private.calendar_events(occurrence_id,connection_id,connection_version,provider_event_id) values(o.id,c.id,c.version,'gt'||replace(o.id::text,'-','')) on conflict(occurrence_id) do nothing;select * into m from app_private.calendar_events where occurrence_id=o.id for update;
 if m.connection_id<>c.id or m.connection_version<>c.version then update app_private.calendar_events set connection_id=c.id,connection_version=c.version,meeting_generation=meeting_generation+1,conference_request_id=gen_random_uuid(),synced_occurrence_version=null,meeting_status='pending',join_url=null,updated_at=now() where occurrence_id=o.id returning * into m;end if;
 return jsonb_build_object('state','ready','mode',c.mode,'desired',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'connection_id',c.id,'connection_version',c.version,'credential_version',c.credential_version,'calendar_id',c.calendar_id,'provider_event_id',m.provider_event_id,'meeting_generation',m.meeting_generation,'conference_request_id',m.conference_request_id,'action',case when o.state='cancelled' then 'cancel' else 'upsert' end,'start_at',o.start_at,'end_at',o.end_at,'tutor_email',email,'title','Git Tutor session'));
end $$;
create function app_private.get_calendar_credentials(p_connection_id uuid,p_connection_version integer,p_job_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.provider_connections%rowtype;v app_private.provider_credential_versions%rowtype;occ uuid;begin
 select e.aggregate_id into occ from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where j.id=p_job_id;perform app_private.calendar_assert_job(occ,p_job_id,p_lease_token);
 select * into c from app_private.provider_connections where id=p_connection_id and state='connected' and version=p_connection_version;if c.id is null or c.mode<>'google' or not app_private.has_role(c.approved_by,'admin') then raise exception 'STATE_CONFLICT';end if;
 if not exists(select 1 from app_private.calendar_events where occurrence_id=occ and connection_id=c.id and connection_version=c.version) then raise exception 'STATE_CONFLICT';end if;select * into v from app_private.provider_credential_versions where id=c.credential_version;
 return jsonb_build_object('provider','google','connection_id',c.id,'credential_version',v.id,'envelope',v.encrypted_credentials);
end $$;
create function app_private.finalize_calendar_sync(p_occurrence_id uuid,p_occurrence_version integer,p_connection_id uuid,p_connection_version integer,p_meeting_generation integer,p_job_id uuid,p_lease_token uuid,p_observation jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o app_private.occurrences%rowtype;c app_private.provider_connections%rowtype;m app_private.calendar_events%rowtype;applied boolean;outcome text:=p_observation->>'outcome';status text;prior app_private.calendar_observations%rowtype;event_id uuid;begin
 perform app_private.calendar_assert_job(p_occurrence_id,p_job_id,p_lease_token);o:=app_private.booking_lock_occurrence(p_occurrence_id);select * into m from app_private.calendar_events where occurrence_id=o.id for update;select * into c from app_private.provider_connections where id=p_connection_id;
 if outcome is null or outcome not in('absent','pending','ready','failed','unknown','revoked') or p_observation->>'provider_event_id' is distinct from m.provider_event_id or length(p_observation::text)>10000 then raise exception 'VALIDATION_ERROR';end if;
 if outcome='ready' and(p_observation->>'join_url' is null or not((c.mode='google' and p_observation->>'join_url' ~ '^https://meet[.]google[.]com/[a-z0-9-]+$')or(c.mode='fake' and p_observation->>'join_url' ~ '^https://meet[.]example[.]test/[a-f0-9-]+/[0-9]+$'))) then raise exception 'VALIDATION_ERROR';end if;
 select * into prior from app_private.calendar_observations where job_id=p_job_id and lease_token=p_lease_token;if prior.id is not null then return jsonb_build_object('applied',prior.applied,'outcome',prior.observation->>'outcome');end if;
 applied:=o.version=p_occurrence_version and m.connection_id=p_connection_id and m.connection_version=p_connection_version and m.meeting_generation=p_meeting_generation and c.version=p_connection_version and c.state='connected' and app_private.has_role(c.approved_by,'admin') and app_private.payment_verified_account(c.approved_by);
 insert into app_private.calendar_observations(occurrence_id,connection_id,connection_version,occurrence_version,meeting_generation,job_id,lease_token,observation,applied) values(o.id,p_connection_id,p_connection_version,p_occurrence_version,p_meeting_generation,p_job_id,p_lease_token,p_observation,applied);
 if applied then status:=case when o.state='cancelled' and outcome='revoked' then 'revoked' when outcome='ready' then 'ready' when outcome='failed' then 'failed' when outcome='revoked' then 'revoked' when outcome in('pending','absent') and m.poll_count>=8 then 'failed' else 'pending' end;
 update app_private.calendar_events set synced_occurrence_version=o.version,meeting_status=status,join_url=case when status='ready' then p_observation->>'join_url' end,etag=p_observation->>'etag',safe_error_code=p_observation->>'safe_error_code',updated_at=now() where occurrence_id=o.id;
 update app_private.occurrences set meeting_status=status where id=o.id;
 if status='ready' and(m.notified_occurrence_version is distinct from o.version or m.notified_generation is distinct from m.meeting_generation) then perform app_private.enqueue_event(gen_random_uuid(),'meeting_ready',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'meeting_generation',m.meeting_generation),'notifications.route');update app_private.calendar_events set notified_occurrence_version=o.version,notified_generation=m.meeting_generation,poll_count=0 where occurrence_id=o.id;end if;
 if status='failed' then perform app_private.enqueue_event(gen_random_uuid(),'meeting_provisioning_failed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version),'notifications.route');end if;
 end if;
 if not applied or(outcome in('pending','absent') and m.poll_count<8) then event_id:=gen_random_uuid();insert into app_private.domain_events(id,event_type,aggregate_id,payload,correlation_id) values(event_id,'calendar_reconciliation_requested',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version),event_id);insert into app_private.outbox_jobs(event_id,purpose,available_at) values(event_id,'calendar.sync',now()+make_interval(secs=>least(30*power(2,m.poll_count)::integer,3600)));if applied then update app_private.calendar_events set poll_count=poll_count+1 where occurrence_id=o.id;end if;end if;
 return jsonb_build_object('applied',applied,'outcome',outcome);
end $$;
create function app_private.rotate_calendar_credentials(p_connection_id uuid,p_connection_version integer,p_previous_credential_version uuid,p_credential_version uuid,p_encrypted_credentials jsonb,p_credential_key_id text,p_job_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.provider_connections%rowtype;proof jsonb;begin
 proof:=app_private.get_calendar_credentials(p_connection_id,p_connection_version,p_job_id,p_lease_token);select * into c from app_private.provider_connections where id=p_connection_id for update;
 if c.state<>'connected' or c.version<>p_connection_version or c.credential_version is distinct from p_previous_credential_version then raise exception 'VERSION_CONFLICT';end if;
 if p_credential_version is null or p_credential_version=p_previous_credential_version or not app_private.calendar_envelope_valid(p_encrypted_credentials,p_credential_key_id) then raise exception 'VALIDATION_ERROR';end if;
 insert into app_private.provider_credential_versions(id,connection_id,encrypted_credentials,credential_key_id) values(p_credential_version,c.id,p_encrypted_credentials,p_credential_key_id);update app_private.provider_connections set credential_version=p_credential_version,updated_at=now() where id=c.id;return jsonb_build_object('credential_version',p_credential_version);
end $$;

do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='api' and p.proname in('connect_fake_calendar','create_calendar_connection_request','get_calendar_connection_request','get_calendar_connection','revoke_calendar_connection','get_occurrence_meeting','get_meeting_access','retry_meeting_provisioning','replace_meeting_access'))or(n.nspname='app_private' and p.proname in('calendar_envelope_valid','calendar_queue_current','record_calendar_connection','calendar_assert_access','calendar_command','calendar_assert_job','prepare_calendar_sync','get_calendar_credentials','finalize_calendar_sync','rotate_calendar_credentials')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('record_calendar_connection','prepare_calendar_sync','get_calendar_credentials','finalize_calendar_sync','rotate_calendar_credentials') then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private from git_tutor_commands;
notify pgrst,'reload schema';
